 17→func newCleanCmd() *cobra.Command {
 18→	var forceFlag bool
 19→
 20→	cmd := &cobra.Command{
 21→		Use:   "clean",
 22→		Short: "Clean up orphaned Entire data",
 23→		Long: `Remove orphaned Entire data (session state, shadow branches, checkpoint metadata, temp files) that wasn't cleaned up automatically.
 24→
 25→This command finds and removes orphaned data from any strategy:
 26→
 27→  Shadow branches (entire/<commit-hash>)
 28→    Normally auto-cleaned when sessions
 29→    are condensed during commits.
 30→
 31→  Session state files (.git/entire-sessions/)
 32→    Track active sessions. Orphaned when no checkpoints or shadow branches
 33→    reference them.
 34→
 35→  Checkpoint metadata (entire/checkpoints/v1 branch)
 36→    Checkpoints are permanent (condensed session history) and are
 37→    never considered orphaned.
 38→
 39→  Temporary files (.entire/tmp/)
 40→    Cached transcripts and other temporary data. Safe to delete when no
 41→    active sessions are using them.
 42→
 43→Default: shows a preview of items that would be deleted.
 44→With --force, actually deletes the orphaned items.
 45→
 46→The entire/checkpoints/v1 branch itself is never deleted.`,
 47→		RunE: func(cmd *cobra.Command, _ []string) error {
 48→			return runClean(cmd.Context(), cmd.OutOrStdout(), forceFlag)
 49→		},
 50→	}
 51→
 52→	cmd.Flags().BoolVarP(&forceFlag, "force", "f", false, "Actually delete items (default: dry run)")
 53→
 54→	return cmd
 55→}
