 57→func runClean(ctx context.Context, w io.Writer, force bool) error {
 58→	// Initialize logging so structured logs go to .entire/logs/ instead of stderr.
 59→	// Error is non-fatal: if logging init fails, logs go to stderr (acceptable fallback).
 60→	logging.SetLogLevelGetter(GetLogLevel)
 61→	if err := logging.Init(ctx, ""); err == nil {
 62→		defer logging.Close()
 63→	}
 64→
 65→	// List all cleanup items
 66→	items, err := strategy.ListAllCleanupItems(ctx)
 67→	if err != nil {
 68→		return fmt.Errorf("failed to list orphaned items: %w", err)
 69→	}
 70→
 71→	// List temp files
 72→	tempFiles, err := listTempFiles(ctx)
 73→	if err != nil {
 74→		// Non-fatal: continue with other cleanup items
 75→		fmt.Fprintf(w, "Warning: failed to list temp files: %v\n", err)
 76→	}
 77→
 78→	return runCleanWithItems(ctx, w, force, items, tempFiles)
 79→}
 80→
 81→// listTempFiles returns files in .entire/tmp/ that are safe to delete,
 82→// excluding files belonging to active sessions.
 83→func listTempFiles(ctx context.Context) ([]string, error) {
 84→	tmpDir, err := paths.AbsPath(ctx, paths.EntireTmpDir)
 85→	if err != nil {
 86→		return nil, fmt.Errorf("failed to get temp dir path: %w", err)
 87→	}
 88→
 89→	entries, err := os.ReadDir(tmpDir)
 90→	if os.IsNotExist(err) {
 91→		return nil, nil
 92→	}
 93→	if err != nil {
 94→		return nil, fmt.Errorf("failed to read temp dir: %w", err)
 95→	}
 96→
 97→	// Build set of active session IDs to protect their temp files
 98→	activeSessionIDs := make(map[string]bool)
 99→	if states, listErr := strategy.ListSessionStates(ctx); listErr == nil {
100→		for _, state := range states {
101→			activeSessionIDs[state.SessionID] = true
102→		}
103→	}
104→
105→	var files []string
106→	for _, entry := range entries {
107→		if entry.IsDir() {
108→			continue
109→		}
110→		// Skip temp files belonging to active sessions (e.g., "session-id.json")
111→		name := entry.Name()
112→		sessionID := strings.TrimSuffix(name, ".json")
113→		if sessionID != name && activeSessionIDs[sessionID] {
114→			continue
115→		}
116→		files = append(files, name)
117→	}
118→	return files, nil
119→}
120→
121→// TempFileDeleteError contains a file name and the error that occurred during deletion.
122→type TempFileDeleteError struct {
123→	File string
124→	Err  error
125→}
126→
127→// deleteTempFiles removes all files in .entire/tmp/.
128→// Returns successfully deleted files and any failures with their error reasons.
129→func deleteTempFiles(ctx context.Context, files []string) (deleted []string, failed []TempFileDeleteError) {
130→	tmpDir, err := paths.AbsPath(ctx, paths.EntireTmpDir)
131→	if err != nil {
132→		// Can't get path - mark all as failed with the same error
133→		for _, file := range files {
134→			failed = append(failed, TempFileDeleteError{File: file, Err: err})
135→		}
136→		return nil, failed
137→	}
138→
139→	for _, file := range files {
140→		path := filepath.Join(tmpDir, file)
141→		if err := os.Remove(path); err != nil {
142→			failed = append(failed, TempFileDeleteError{File: file, Err: err})
143→		} else {
144→			deleted = append(deleted, file)
145→		}
146→	}
147→	return deleted, failed
148→}
