150→// runCleanWithItems is the core logic for cleaning orphaned items.
151→// Separated for testability.
152→func runCleanWithItems(ctx context.Context, w io.Writer, force bool, items []strategy.CleanupItem, tempFiles []string) error {
153→	// Handle no items case
154→	if len(items) == 0 && len(tempFiles) == 0 {
155→		fmt.Fprintln(w, "No orphaned items to clean up.")
156→		return nil
157→	}
158→
159→	// Group items by type for display
160→	var branches, states, checkpoints []strategy.CleanupItem
161→	for _, item := range items {
162→		switch item.Type {
163→		case strategy.CleanupTypeShadowBranch:
164→			branches = append(branches, item)
165→		case strategy.CleanupTypeSessionState:
166→			states = append(states, item)
167→		case strategy.CleanupTypeCheckpoint:
168→			checkpoints = append(checkpoints, item)
169→		}
170→	}
171→
172→	// Preview mode (default)
173→	if !force {
174→		totalItems := len(items) + len(tempFiles)
175→		fmt.Fprintf(w, "Found %d items to clean:\n\n", totalItems)
176→
177→		if len(branches) > 0 {
178→			fmt.Fprintf(w, "Shadow branches (%d):\n", len(branches))
179→			for _, item := range branches {
180→				fmt.Fprintf(w, "  %s\n", item.ID)
181→			}
182→			fmt.Fprintln(w)
183→		}
184→
185→		if len(states) > 0 {
186→			fmt.Fprintf(w, "Session states (%d):\n", len(states))
187→			for _, item := range states {
188→				fmt.Fprintf(w, "  %s\n", item.ID)
189→			}
190→			fmt.Fprintln(w)
191→		}
192→
193→		if len(checkpoints) > 0 {
194→			fmt.Fprintf(w, "Checkpoint metadata (%d):\n", len(checkpoints))
195→			for _, item := range checkpoints {
196→				fmt.Fprintf(w, "  %s\n", item.ID)
197→			}
198→			fmt.Fprintln(w)
199→		}
200→
201→		if len(tempFiles) > 0 {
202→			fmt.Fprintf(w, "Temp files (%d):\n", len(tempFiles))
203→			for _, file := range tempFiles {
204→				fmt.Fprintf(w, "  %s\n", file)
205→			}
206→			fmt.Fprintln(w)
207→		}
208→
209→		fmt.Fprintln(w, "Run with --force to delete these items.")
210→		return nil
211→	}
212→
213→	// Force mode - delete items
214→	result, err := strategy.DeleteAllCleanupItems(ctx, items)
215→	if err != nil {
216→		return fmt.Errorf("failed to delete orphaned items: %w", err)
217→	}
218→
219→	// Delete temp files
220→	deletedTempFiles, failedTempFiles := deleteTempFiles(ctx, tempFiles)
221→
222→	// Report results
223→	totalDeleted := len(result.ShadowBranches) + len(result.SessionStates) + len(result.Checkpoints) + len(deletedTempFiles)
224→	totalFailed := len(result.FailedBranches) + len(result.FailedStates) + len(result.FailedCheckpoints) + len(failedTempFiles)
225→
226→	if totalDeleted > 0 {
227→		fmt.Fprintf(w, "Deleted %d items:\n", totalDeleted)
228→
229→		if len(result.ShadowBranches) > 0 {
230→			fmt.Fprintf(w, "\n  Shadow branches (%d):\n", len(result.ShadowBranches))
231→			for _, branch := range result.ShadowBranches {
232→				fmt.Fprintf(w, "    %s\n", branch)
233→			}
234→		}
235→
236→		if len(result.SessionStates) > 0 {
237→			fmt.Fprintf(w, "\n  Session states (%d):\n", len(result.SessionStates))
238→			for _, state := range result.SessionStates {
239→				fmt.Fprintf(w, "    %s\n", state)
240→			}
241→		}
242→
243→		if len(result.Checkpoints) > 0 {
244→			fmt.Fprintf(w, "\n  Checkpoints (%d):\n", len(result.Checkpoints))
245→			for _, cp := range result.Checkpoints {
246→				fmt.Fprintf(w, "    %s\n", cp)
247→			}
248→		}
249→
250→		if len(deletedTempFiles) > 0 {
251→			fmt.Fprintf(w, "\n  Temp files (%d):\n", len(deletedTempFiles))
252→			for _, file := range deletedTempFiles {
253→				fmt.Fprintf(w, "    %s\n", file)
254→			}
255→		}
256→	}
257→
258→	if totalFailed > 0 {
259→		fmt.Fprintf(w, "\nFailed to delete %d items:\n", totalFailed)
260→
261→		if len(result.FailedBranches) > 0 {
262→			fmt.Fprintf(w, "\n  Shadow branches:\n")
263→			for _, branch := range result.FailedBranches {
264→				fmt.Fprintf(w, "    %s\n", branch)
265→			}
266→		}
267→
268→		if len(result.FailedStates) > 0 {
269→			fmt.Fprintf(w, "\n  Session states:\n")
270→			for _, state := range result.FailedStates {
271→				fmt.Fprintf(w, "    %s\n", state)
272→			}
273→		}
274→
275→		if len(result.FailedCheckpoints) > 0 {
276→			fmt.Fprintf(w, "\n  Checkpoints:\n")
277→			for _, cp := range result.FailedCheckpoints {
278→				fmt.Fprintf(w, "    %s\n", cp)
279→			}
280→		}
281→
282→		if len(failedTempFiles) > 0 {
283→			fmt.Fprintf(w, "\n  Temp files:\n")
284→			for _, fe := range failedTempFiles {
285→				fmt.Fprintf(w, "    %s: %v\n", fe.File, fe.Err)
286→			}
287→		}
288→
289→		return fmt.Errorf("failed to delete %d items", totalFailed)
290→	}
291→
292→	return nil
293→}
