 17→func setupCleanTestRepo(t *testing.T) (*git.Repository, plumbing.Hash) {
 18→	t.Helper()
 19→
 20→	dir := t.TempDir()
 21→	repo, err := git.PlainInit(dir, false)
 22→	if err != nil {
 23→		t.Fatalf("failed to init git repo: %v", err)
 24→	}
 25→
 26→	t.Chdir(dir)
 27→	paths.ClearWorktreeRootCache()
 28→
 29→	// Create initial commit
 30→	emptyTree := &object.Tree{Entries: []object.TreeEntry{}}
 31→	obj := repo.Storer.NewEncodedObject()
 32→	if err := emptyTree.Encode(obj); err != nil {
 33→		t.Fatalf("failed to encode empty tree: %v", err)
 34→	}
 35→	emptyTreeHash, err := repo.Storer.SetEncodedObject(obj)
 36→	if err != nil {
 37→		t.Fatalf("failed to store empty tree: %v", err)
 38→	}
 39→
 40→	sig := object.Signature{Name: "test", Email: "test@test.com"}
 41→	commit := &object.Commit{
 42→		TreeHash:  emptyTreeHash,
 43→		Author:    sig,
 44→		Committer: sig,
 45→		Message:   "initial commit",
 46→	}
 47→	commitObj := repo.Storer.NewEncodedObject()
 48→	if err := commit.Encode(commitObj); err != nil {
 49→		t.Fatalf("failed to encode commit: %v", err)
 50→	}
 51→	commitHash, err := repo.Storer.SetEncodedObject(commitObj)
 52→	if err != nil {
 53→		t.Fatalf("failed to store commit: %v", err)
 54→	}
 55→
 56→	// Create HEAD and master references
 57→	headRef := plumbing.NewSymbolicReference(plumbing.HEAD, plumbing.NewBranchReferenceName("master"))
 58→	if err := repo.Storer.SetReference(headRef); err != nil {
 59→		t.Fatalf("failed to set HEAD: %v", err)
 60→	}
 61→	masterRef := plumbing.NewHashReference(plumbing.NewBranchReferenceName("master"), commitHash)
 62→	if err := repo.Storer.SetReference(masterRef); err != nil {
 63→		t.Fatalf("failed to set master: %v", err)
 64→	}
 65→
 66→	return repo, commitHash
 67→}
