 69→func TestRunClean_NoOrphanedItems(t *testing.T) {
 70→	setupCleanTestRepo(t)
 71→
 72→	var stdout bytes.Buffer
 73→	err := runClean(context.Background(), &stdout, false)
 74→	if err != nil {
