 84→func TestRunClean_PreviewMode(t *testing.T) {
 85→	repo, commitHash := setupCleanTestRepo(t)
 86→
 87→	// Create shadow branches
 88→	shadowBranches := []string{"entire/abc1234", "entire/def5678"}
 89→	for _, b := range shadowBranches {
 90→		ref := plumbing.NewHashReference(plumbing.NewBranchReferenceName(b), commitHash)
 91→		if err := repo.Storer.SetReference(ref); err != nil {
 92→			t.Fatalf("failed to create branch %s: %v", b, err)
 93→		}
 94→	}
 95→
 96→	// Also create entire/checkpoints/v1 (should NOT be listed)
 97→	sessionsRef := plumbing.NewHashReference(plumbing.NewBranchReferenceName(paths.MetadataBranchName), commitHash)
 98→	if err := repo.Storer.SetReference(sessionsRef); err != nil {
 99→		t.Fatalf("failed to create %s: %v", paths.MetadataBranchName, err)
100→	}
101→
102→	var stdout bytes.Buffer
103→	err := runClean(context.Background(), &stdout, false) // force=false
104→	if err != nil {
105→		t.Fatalf("runClean() error = %v", err)
106→	}
107→
108→	output := stdout.String()
109→
110→	// Should show preview header
111→	if !strings.Contains(output, "items to clean") {
112→		t.Errorf("Expected 'items to clean' in output, got: %s", output)
113→	}
114→
115→	// Should list the shadow branches
116→	if !strings.Contains(output, "entire/abc1234") {
117→		t.Errorf("Expected 'entire/abc1234' in output, got: %s", output)
118→	}
119→	if !strings.Contains(output, "entire/def5678") {
120→		t.Errorf("Expected 'entire/def5678' in output, got: %s", output)
121→	}
122→
123→	// Should NOT list entire/checkpoints/v1
124→	if strings.Contains(output, paths.MetadataBranchName) {
125→		t.Errorf("Should not list '%s', got: %s", paths.MetadataBranchName, output)
126→	}
127→
128→	// Should prompt to use --force
129→	if !strings.Contains(output, "--force") {
130→		t.Errorf("Expected '--force' prompt in output, got: %s", output)
131→	}
132→
133→	// Branches should still exist (preview mode doesn't delete)
134→	for _, b := range shadowBranches {
135→		refName := plumbing.NewBranchReferenceName(b)
136→		if _, err := repo.Reference(refName, true); err != nil {
137→			t.Errorf("Branch %s should still exist after preview", b)
138→		}
139→	}
140→}
