 18→// setupResetTestRepo is a test helper that creates a git repository with an initial commit.
 19→// This is intentionally duplicated from clean_test.go to keep test files independent.
 20→//
 21→//nolint:dupl // Test setup code duplication is acceptable for test isolation
 22→func setupResetTestRepo(t *testing.T) (*git.Repository, plumbing.Hash) {
 23→	t.Helper()
 24→
 25→	dir := t.TempDir()
 26→	repo, err := git.PlainInit(dir, false)
 27→	if err != nil {
 28→		t.Fatalf("failed to init git repo: %v", err)
 29→	}
 30→
 31→	t.Chdir(dir)
 32→	paths.ClearWorktreeRootCache()
 33→
 34→	// Create initial commit
 35→	emptyTree := &object.Tree{Entries: []object.TreeEntry{}}
 36→	obj := repo.Storer.NewEncodedObject()
 37→	if err := emptyTree.Encode(obj); err != nil {
 38→		t.Fatalf("failed to encode empty tree: %v", err)
 39→	}
 40→	emptyTreeHash, err := repo.Storer.SetEncodedObject(obj)
 41→	if err != nil {
 42→		t.Fatalf("failed to store empty tree: %v", err)
 43→	}
 44→
 45→	sig := object.Signature{Name: "test", Email: "test@test.com"}
 46→	commit := &object.Commit{
 47→		TreeHash:  emptyTreeHash,
 48→		Author:    sig,
 49→		Committer: sig,
 50→		Message:   "initial commit",
 51→	}
 52→	commitObj := repo.Storer.NewEncodedObject()
 53→	if err := commit.Encode(commitObj); err != nil {
 54→		t.Fatalf("failed to encode commit: %v", err)
 55→	}
 56→	commitHash, err := repo.Storer.SetEncodedObject(commitObj)
 57→	if err != nil {
 58→		t.Fatalf("failed to store commit: %v", err)
 59→	}
 60→
 61→	// Create HEAD and master references
 62→	headRef := plumbing.NewSymbolicReference(plumbing.HEAD, plumbing.NewBranchReferenceName("master"))
 63→	if err := repo.Storer.SetReference(headRef); err != nil {
 64→		t.Fatalf("failed to set HEAD: %v", err)
 65→	}
 66→	masterRef := plumbing.NewHashReference(plumbing.NewBranchReferenceName("master"), commitHash)
 67→	if err := repo.Storer.SetReference(masterRef); err != nil {
 68→		t.Fatalf("failed to set master: %v", err)
 69→	}
 70→
 71→	return repo, commitHash
 72→}
